StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_ControllerStat
//	CREATOR:				Helgevold - William Veim
// REQUIREMENTS: NX CPU
//
// DESCRTIPTION: 	Collects status information from controller and outputs alarm
//								
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// VERSION LOG:
//	VERSION			DATE					SIGN							DESCRIPTION
//	1.0.0					2024-11-18			William Veim        		Initial release
//	1.1.0					2025-04-30			Ruben Byman				Added alarm and SMS_Error
//	1.1.1					2025-09-12			William Veim				Bugfix controller cabinet/TAG
//	1.1.2					2025-10-16			William Veim				Bugfix SD backup
//	1.1.3					2025-11-06			William Veim				Added deviation >10min allowed for time sync fault
//	1.1.4					2026-04-15			Ruben Byman				Bugfix to avoid time deviation error around midnight when SCADA clock doesn't update quickly enough
//	1.1.5					2026-06-16			Ruben Byman				Bugfix error check
//	1.1.6					2026-07-10			Ruben Byman				Changed Max Execution Time to show max exec time today
//	
//================================================================================================================================

//Reads task time
FB_TaskTime(ENI:=TRUE, Cfg_MaxExecPercent_Limit:=95);

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

//NB!! REMEMBER TO UPDATE!!!!
Ext_ControllerStat.EXT_Engineering.LibraryVersion:='3.0.12';

Ext_ControllerStat.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

// Retrieving input data
//----------------------------
Ext_ControllerStat.EXT_General.Connected_ControlCabinet:=Cfg_ConnCab;
Ext_ControllerStat.EXT_General.Process_TAG:= Cfg_ControllerName;
Ext_ControllerStat.EXT_Engineering.UnitVersion:=Cfg_ControllerModel;

IF NOT Ext_ControllerStat.INT_Data.Initialise THEN
	
	//State config
	Ext_ControllerStat.EXT_Engineering.StateCfg_1.Cfg_Quality:=1; 		//Controller fault = Equipment failiure
	Ext_ControllerStat.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; 	//Controller fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; 		//NX bus fault = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; 	//NX bus fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; 		//EIP fault = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; 	//EIP fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_4.Cfg_Quality:=0; 		//Task time exceeded = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; 	//Task time exceeded = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_5.Cfg_Quality:=3; 		//SD card backup fault = Warning
	Ext_ControllerStat.EXT_Engineering.StateCfg_5.Cfg_Alarm:=TRUE; 	//SD card backup fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_6.Cfg_Quality:=0; 		//Time sync fault = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_6.Cfg_Alarm:=TRUE; 	//Time sync fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_7.Cfg_Quality:=1; 		//SMS modem fault = Equipment failiure
	Ext_ControllerStat.EXT_Engineering.StateCfg_7.Cfg_Alarm:=TRUE; 	//SMS modem fault = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_8.Cfg_Quality:=0; 		//Alarm array out of range = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_8.Cfg_Alarm:=TRUE; 	//Alarm array out of range = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_9.Cfg_Quality:=3; 		//High temperature CPU = Warning
	Ext_ControllerStat.EXT_Engineering.StateCfg_9.Cfg_Alarm:=TRUE; 	//High temperature CPUt = Alarm
	Ext_ControllerStat.EXT_Engineering.StateCfg_10.Cfg_Quality:=0; 		//Cooling fan CPU fault = Diagnostic
	Ext_ControllerStat.EXT_Engineering.StateCfg_10.Cfg_Alarm:=TRUE; 	//Cooling fan CPU fault = Alarm
 
 	//Alarm settings
	Ext_ControllerStat.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_ControllerStat.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_ControllerStat.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_ControllerStat.INT_Data.Initialise:=TRUE;
	
END_IF;
 
(*************************************************************************
 *	RETRIEVING CONTROLLER STATE
 *************************************************************************)

//Retrieve firmware version
IF P_First_Run THEN
	Clear(Ext_ControllerStat.EXT_Engineering.FirmwareVersion);
	HE_StrConcatAdv(InOut:=Ext_ControllerStat.EXT_Engineering.FirmwareVersion, In_Static:= USINT_TO_STRING(_SystemSWVersion[0]) , In_Variable:='.');
	HE_StrConcatAdv(InOut:=Ext_ControllerStat.EXT_Engineering.FirmwareVersion, In_Static:= USINT_TO_STRING(_SystemSWVersion[1]) , In_Variable:='');
END_IF;

Ext_ControllerStat.EXT_Engineering.Controller_Clock:=  LEFT(TodToString(TruncTod(DT_TO_TOD(In:=GetTime()), _SEC)),5);
Ext_ControllerStat.EXT_Statistics.PowerOnCount := 		UDINT_TO_UINT(_PowerOnCount);
Ext_ControllerStat.EXT_Statistics.PowerOnTime := 			_PowerOnHour;
Ext_ControllerStat.EXT_Engineering.MainTask_Time:= 	FB_TaskTime.Avg_TaskTime;
Ext_ControllerStat.EXT_Engineering.MaxTask_Time:= 		FB_TaskTime.Max_TaskTimeToday;

IF P_First_Run THEN
Ext_ControllerStat.EXT_Statistics.RestartDate_Controller:=DateToString(DT_TO_DATE(GetTime()));
END_IF;

Wrk_TaskTime_Exceeded := FB_TaskTime.Sts_Alarm;

(*************************************************************************
 *	DECODE STATE (CONTROLLER, NX and EIP)
 *************************************************************************)
 
 // Decode controller state
//----------------------------
Wrk_PLC_ErrSta := _PLC_ErrSta AND WORD#16#00F0;
IF Wrk_PLC_ErrSta = 16#0 THEN
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'No fault';
ELSIF TestABit(In:=Wrk_PLC_ErrSta,Pos:= 4) THEN
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'Observation fault';
ELSIF TestABit(In:=Wrk_PLC_ErrSta,Pos:= 5) THEN
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'Minor fault';
ELSIF TestABit(In:=Wrk_PLC_ErrSta,Pos:= 6) THEN
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'Partial fault';
ELSIF TestABit(In:=Wrk_PLC_ErrSta,Pos:= 7) THEN
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'Major fault';
ELSE
	Ext_ControllerStat.EXT_Engineering.ControllerError := 'Unknown';
END_IF;
Wrk_PLC_Error := Wrk_PLC_ErrSta > 16#15;		//Ignores Observation error for State Control

// Decode NX bus state
//----------------------------
Wrk_NXB_ErrSta := _NXB_ErrSta AND WORD#16#00F0;
IF Wrk_NXB_ErrSta = 16#0 THEN
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'No fault';
ELSIF TestABit(In:=Wrk_NXB_ErrSta,Pos:= 4) THEN
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'Observation fault';
ELSIF TestABit(In:=Wrk_NXB_ErrSta,Pos:= 5) THEN
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'Minor fault';
ELSIF TestABit(In:=Wrk_NXB_ErrSta,Pos:= 6) THEN
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'Partial fault';
ELSIF TestABit(In:=Wrk_NXB_ErrSta,Pos:= 7) THEN
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'Major fault';
ELSE
	Ext_ControllerStat.EXT_Engineering.NXBusError := 'Unknown';
END_IF;
Wrk_NXB_Error := Wrk_NXB_ErrSta > 16#15;		//Ignores Observation error for State Control

// Decode EIP state
//----------------------------
Wrk_EIP_ErrSta := _EIP_ErrSta AND WORD#16#00F0;
IF Wrk_EIP_ErrSta = 16#0 THEN
	Ext_ControllerStat.EXT_Engineering.EIPError := 'No fault';
ELSIF TestABit(In:=Wrk_EIP_ErrSta,Pos:= 4) THEN
	Ext_ControllerStat.EXT_Engineering.EIPError := 'Observation fault';
ELSIF TestABit(In:=Wrk_EIP_ErrSta,Pos:= 5) THEN
	Ext_ControllerStat.EXT_Engineering.EIPError := 'Minor fault';
ELSIF TestABit(In:=Wrk_EIP_ErrSta,Pos:= 6) THEN
	Ext_ControllerStat.EXT_Engineering.EIPError := 'Partial fault';
ELSIF TestABit(In:=Wrk_EIP_ErrSta,Pos:= 7) THEN
	Ext_ControllerStat.EXT_Engineering.EIPError := 'Major fault';
ELSE
	Ext_ControllerStat.EXT_Engineering.EIPError := 'Unknown';
END_IF;
Wrk_EIP_Error := Wrk_EIP_ErrSta > 16#15;		//Ignores Observation error for State Control

(*************************************************************************
 *	TIME SYNC (NTP and summer/winter)
 *************************************************************************)
 
FB_TimeSync(ENS:=TRUE, 
				TimeZone_Active:=Cfg_TimeSync_Activate, 
				TimeSync_Exce=>Out_TimeSync_ExcTime);

(*************************************************************************
 *	HOLD OUTPUT CONFIG (Retain output while controller stop)
 *************************************************************************)
 
IF Cfg_HoldOutput THEN
	_DeviceOutHoldCfg := 16#A5A5;
ELSE
	_DeviceOutHoldCfg := 16#0;
END_IF;

Sts_HoldOutput := _DeviceOutHoldStatus;

(*************************************************************************
 *	BACKUP TO SD CARD
 *************************************************************************)
 
Wrk_CPUStartupDelay(In:=TRUE, PT:=TIME#12h); //Ensure no backup after download/transfer (12h block time)
SD_Date_Actual := DT_TO_DATE(GetTime());
SD_Time_Actual := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);

IF SD_Date_Actual <> SD_Date_Sample AND Cfg_SDCard_InUse THEN
	Inc(SD_Days_Sample);
	SD_Date_Sample:=SD_Date_Actual;
END_IF;

IF Cfg_SDCard_InUse AND SD_Days_Sample >= Cfg_SDBackup_Days AND Cfg_SDBackup_Time = SD_Time_Actual AND Wrk_CPUStartupDelay.Q THEN
	FB_SD_Backup.Inp_StartBackup:=TRUE;
	Clear(SD_Days_Sample);
ELSE
	FB_SD_Backup.Inp_StartBackup:=FALSE;
END_IF;

Wrk_SDBackup_Fault := Cfg_SDCard_InUse AND (FB_SD_Backup.Sts_BackupFailed OR FB_SD_Backup.Sts_SD_Unavailable);

FB_SD_Backup(ENI:=Cfg_SDCard_InUse, 
					Cfg_BackupInterval:=TIME#10d);

(*************************************************************************
 *	STATE AND FAULT CONTROL
 *************************************************************************)

//Checks if SCADA clock is on the wrong side of midnight, and adds/subtracts 24h to/from deviation to mitigate
IF SUB_TOD_TOD(In1:=HE_Str2TOD(DELETE(In:=Ext_ControllerStat.EXT_Engineering.SCADA_Clock, L:=1, P:=3)), In2:=DT_TO_TOD(In:=GetTime())) > TIME#23h THEN
	Wrk_TimeDeviation := SUB_TIME(In1:=SUB_TOD_TOD(In1:=HE_Str2TOD(DELETE(In:=Ext_ControllerStat.EXT_Engineering.SCADA_Clock, L:=1, P:=3)), In2:=DT_TO_TOD(In:=GetTime())), In2:=TIME#24h);
ELSIF SUB_TOD_TOD(In1:=HE_Str2TOD(DELETE(In:=Ext_ControllerStat.EXT_Engineering.SCADA_Clock, L:=1, P:=3)), In2:=DT_TO_TOD(GetTime())) < TIME#-23h THEN
	Wrk_TimeDeviation := ADD_TIME(In1:=SUB_TOD_TOD(In1:=HE_Str2TOD(DELETE(In:=Ext_ControllerStat.EXT_Engineering.SCADA_Clock, L:=1, P:=3)), In2:=DT_TO_TOD(In:=GetTime())), In2:=TIME#24h);
ELSE
	Wrk_TimeDeviation:= SUB_TOD_TOD(In1:=HE_Str2TOD(DELETE(In:=Ext_ControllerStat.EXT_Engineering.SCADA_Clock, L:=1, P:=3)), In2:=DT_TO_TOD(In:=GetTime()));
END_IF;

Wrk_TimeSync_Fault:= FB_TimeSync.TimeSync_Fault OR Wrk_TimeDeviation > TIME#10m OR Wrk_TimeDeviation < TIME#-10m;
 
Wrk_SMS_Error := Inp_SMS_Error;
Wrk_ArrayOutOfRange:= Inp_AlarmArrayOutOfRange;

//Resetter variabler før løkke
Ext_ControllerStat.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState := 0;

//STATE 1 - Controller error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_PLC_Error, 
							Inp_Desc:='Controller fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[0], 
							Sts_AlarmState=>Wrk_AlarmState[0]);

//STATE 2 - NXBus error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_NXB_Error, 
							Inp_Desc:='NX bus fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[1], 
							Sts_AlarmState=>Wrk_AlarmState[1]);

//STATE 3 - EIP error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_EIP_Error, 
							Inp_Desc:='EIP fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[2], 
							Sts_AlarmState=>Wrk_AlarmState[2]);

//STATE 4 - Task time exceeded
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_TaskTime_Exceeded, 
							Inp_Desc:='Task time exceeded', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[3], 
							Sts_AlarmState=>Wrk_AlarmState[3]);

//STATE 5 - SD card backup error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Cfg_SDCard_InUse, 
							Inp_State:=Wrk_SDBackup_Fault, 
							Inp_Desc:='SD card backup fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[4], 
							Sts_AlarmState=>Wrk_AlarmState[4]);

//STATE 6 - Time sync error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_6, 
							Inp_Visibility:=Cfg_TimeSync_Activate, 
							Inp_State:=Wrk_TimeSync_Fault, 
							Inp_Desc:='Time sync fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[5], 
							Sts_AlarmState=>Wrk_AlarmState[5]);

//STATE 7 - SMS error
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_7, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_SMS_Error, 
							Inp_Desc:='SMS modem fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[6], 
							Sts_AlarmState=>Wrk_AlarmState[6]);

//STATE 8 - Alarm array fault
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_8, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ArrayOutOfRange, 
							Inp_Desc:='Array out of range', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[7], 
							Sts_AlarmState=>Wrk_AlarmState[7]);

//STATE 9 - Alarm high temperature
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_9, 
							Inp_Visibility:=TRUE, 
							Inp_State:=_SelfTest_HighTemperature, 
							Inp_Desc:='High temperature', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[8], 
							Sts_AlarmState=>Wrk_AlarmState[8]);

//STATE 10 - Cooling fan fault
HE_StateControl(EXT_StateData:=Ext_ControllerStat.EXT_Engineering.StateCfg_10, 
							Inp_Visibility:=TRUE, 
							Inp_State:=_SelfTest_LowFanRevolution, 
							Inp_Desc:='Cooling fan fault', 
							Sts_Quality:=Ext_ControllerStat.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmSuffix[9], 
							Sts_AlarmState=>Wrk_AlarmState[9]);

Wrk_ActionState := 0;	//Forces action to always be 0, not relevant for Controller Stat

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_ControllerStat.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_ControllerStat.EXT_General.LocationIndex,
								 Inp_AlarmSupress:=FALSE, 
								 Inp_AlmSuppressDesc:='', 
								 Inp_Connected_Cabinet:=Cfg_ConnCab, 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:=Cfg_ControllerName,
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_ControllerStat.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	UPDATING BLOCK OUTPUTS
 *************************************************************************)

//Writing Outputs
Sts_Alarm:=							Wrk_AlarmTriggered;
Sts_ControllerFault := 			Wrk_PLC_Error;
Sts_NXBusFault := 				Wrk_NXB_Error;
Sts_EIPFault := 						Wrk_EIP_Error;
Sts_SDBackup_Fault := 		Wrk_SDBackup_Fault;
Sts_TimeSync_Fault := 			Wrk_TimeSync_Fault;
Sts_TaskTime_Exceeded :=	Wrk_TaskTime_Exceeded;
